Flux<StockEvent> putAway(LineReader reader) {
    return Flux.<DeliveryLine>generate(sink -> {                 // 1. a cold source, pulled on demand
            String line = reader.readLine();
            if (line == null) sink.complete(); else sink.next(parseLine(line));
        })
        .subscribeOn(Schedulers.boundedElastic())                // 2. the blocking read runs elsewhere
        .<StockEvent>map(l -> new Stocked(l.item()))
        .doFinally(signal -> log("delivery ended: " + signal))  // 3. every ending
        .onErrorResume(e -> Flux.just(new Aborted(e.getMessage())));   // 4. upstream errors only
}

