fun putAway(reader: LineReader): Flow<StockEvent> =
    flow {                                                     // 1. a cold source, plain step-by-step code
        while (true) emit(parseLine(reader.readLine() ?: break))
    }
        .flowOn(Dispatchers.IO)                                // 2. the blocking read runs elsewhere
        .map<DeliveryLine, StockEvent> { StockEvent.Stocked(it.item) }
        .onCompletion { cause -> log("delivery ended: $cause") } // 3. every ending
        .catch { e -> emit(StockEvent.Aborted(e.message ?: "error")) }   // 4. upstream errors only

