Flux<Item> aisleItems(String aisle) {
    return shop.page(aisle, null)
        .expand(p -> p.nextCursor() == null ? Mono.empty() : shop.page(aisle, p.nextCursor()))
        .flatMapIterable(ItemPage::items);
}

void exportPrices(String aisle, Path out) throws IOException {
    try (BufferedWriter writer = Files.newBufferedWriter(out)) {
        aisleItems(aisle)
            .filter(i -> i.priceCents() > 0)             // 2. build: nothing runs yet
            .map(Export::format)
            .publishOn(Schedulers.boundedElastic())      // 3. the blocking writes run elsewhere
            .doOnNext(line -> write(writer, line))
            .blockLast();                                //    runs it
    }
}

